//#region src/utils/help_text.ts
const HELP_WRAP = 78;
const WRAP_INDENT = "    ";
const helpWidth = () => {
	const columns = process.stderr.columns ?? process.stdout.columns;
	if (typeof columns !== "number" || !Number.isFinite(columns) || columns < 1) return 78;
	return Math.max(24, columns - 1);
};
const helpCsv = (label, items, width = helpWidth()) => {
	if (items.length === 0) return "";
	const prefix = `${label}:`;
	const lines = [];
	let line = prefix;
	for (const item of items) {
		const addition = line === prefix ? ` ${item}` : `, ${item}`;
		if (line.length + addition.length <= width) {
			line += addition;
			continue;
		}
		if (line === prefix) lines.push(prefix);
		else lines.push(`${line},`);
		line = `${WRAP_INDENT}${item}`;
	}
	lines.push(line);
	return lines.join("\n");
};
const helpEpilogue = (...blocks) => ["", ...blocks.filter((block) => block !== "")].join("\n");
//#endregion
export { HELP_WRAP, helpCsv, helpEpilogue, helpWidth };
